package main

import (
	"fmt"
	"unicode"
)

func main() {
	text := "Hello World! How are you?"
	charCount := make(map[rune]int)

	for _, c := range text {
		if unicode.IsLetter(c) || unicode.IsDigit(c) {
			c = unicode.ToLower(c)
			charCount[c]++
		}
	}

	fmt.Println("原文本:", text)
	fmt.Println("
字符出现频率:")

	for char, count := range charCount {
		fmt.Printf("'%c': %d
", char, count)
	}

	var mostCommon rune
	maxCount := 0
	for char, count := range charCount {
		if count > maxCount {
			mostCommon = char
			maxCount = count
		}
	}

	fmt.Printf("
出现最多的字符: '%c' (%d次)
", mostCommon, maxCount)
}
